export function getKnowledgeArticleReadTime(article: KnowledgeArticleMeta): string {
  const text = [
    article.subtitle,
    ...article.contentSections.flatMap((section) => [
      section.title,
      ...section.paragraphs,
      ...(section.list ?? []),
      section.callout?.title ?? "",
      section.callout?.text ?? "",
    ]),
    ...(article.steps ?? []).flatMap((step) => [step.name, step.text]),
    ...(article.faq ?? []).flatMap((item) => [item.question, item.answer]),
  ].join(" ");
  const words = text.trim().split(/\s+/).filter(Boolean).length;
  return `Около ${Math.max(1, Math.ceil(words / 160))} мин чтения`;
}

