for (const article of KNOWLEDGE_ARTICLES) {
  article.readTime = getKnowledgeArticleReadTime(article);
}

export function getKnowledgeArticleBySlug(
  slug: string
): KnowledgeArticleMeta | undefined {
  const cleanSlug = slug.replace(/^\/baza-znaniy\//, "").replace(/^\//, "");
  return KNOWLEDGE_ARTICLES.find((a) => a.slug === cleanSlug);
}

export function getRelatedArticles(
  slug: string,
  limit: number = 3
): KnowledgeArticleMeta[] {
  const current = getKnowledgeArticleBySlug(slug);
  if (!current) return KNOWLEDGE_ARTICLES.slice(0, limit);

  const curated = (current.relatedSlugs ?? [])
    .map(getKnowledgeArticleBySlug)
    .filter((article): article is KnowledgeArticleMeta => Boolean(article) && article?.slug !== current.slug);
  const category = KNOWLEDGE_ARTICLES.filter(article => article.category === current.category);
  const nextInCategory = category[(category.findIndex(article => article.slug === current.slug) + 1) % category.length];
  // Keep curated recommendations and one topic neighbour so every article can
  // be discovered from another article, in addition to the category hub.
  const candidates = [...curated.slice(0, Math.max(0, limit - 1)), nextInCategory, ...curated,
    ...category, ...KNOWLEDGE_ARTICLES];
  return [...new Map(candidates.filter(article => article && article.slug !== current.slug)
    .map(article => [article.slug, article])).values()].slice(0, Math.max(0, limit));
}
